void send_preamble(float out[192], uint32_t *cnt, const pream_t type)
{
    if (type == PREAM_BERT)
    {
        for (uint16_t i = 0; i < 192 / 2; i++)
        {
            out[(*cnt)++] = -3.0;
            out[(*cnt)++] = +3.0;
        }
    }
    else
    {
        for (uint16_t i = 0; i < 192 / 2; i++)
        {
            out[(*cnt)++] = +3.0;
            out[(*cnt)++] = -3.0;
        }
    }
}

