functions.slice_symbols:
void slice_symbols(uint16_t out[2 * 184], const float inp[184])
{
    for (uint8_t i = 0; i < 184; i++)
    {
        if (inp[i] >= symbol_list[3])
        {
            out[i * 2 + 1] = 0xFFFF;
        }
        else if (inp[i] >= symbol_list[2])
        {
            out[i * 2 + 1] = -(float)0xFFFF / (symbol_list[3] - symbol_list[2]) * symbol_list[2] +
                             inp[i] * (float)0xFFFF / (symbol_list[3] - symbol_list[2]);
        }
        else if (inp[i] >= symbol_list[1])
        {
            out[i * 2 + 1] = 0x0000;
        }
        else if (inp[i] >= symbol_list[0])
        {
            out[i * 2 + 1] = (float)0xFFFF / (symbol_list[1] - symbol_list[0]) * symbol_list[1] -
                             inp[i] * (float)0xFFFF / (symbol_list[1] - symbol_list[0]);
        }
        else
        {
            out[i * 2 + 1] = 0xFFFF;
        }
        if (inp[i] >= symbol_list[2])
        {
            out[i * 2] = 0x0000;
        }
        else if (inp[i] >= symbol_list[1])
        {
            out[i * 2] = 0x7FFF - inp[i] * (float)0xFFFF / (symbol_list[2] - symbol_list[1]);
        }
        else
        {
            out[i * 2] = 0xFFFF;
        }
    }
}

