functions.decode_callsign_value:
void decode_callsign_value(uint8_t *outp, const uint64_t inp)
{
    uint64_t encoded = inp;
    uint8_t start = 0;
    if (encoded >= (262144000000000UL))
    {
        if (encoded == 0xFFFFFFFFFFFF)
        {
            sprintf((char *)outp, "@ALL");
            return;
        }
        else if (encoded <= (268697600000000UL))
        {
            start = 1;
            encoded -= (262144000000000UL);
            outp[0] = '#';
        }
        else
        {
            return;
        }
    }
    uint8_t i = start;
    while (encoded > 0)
    {
        outp[i] = " ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-/."[encoded % 40];
        encoded /= 40;
        i++;
    }
    outp[i] = 0;
}

functions.decode_callsign_bytes:
void decode_callsign_bytes(uint8_t *outp, const uint8_t inp[6])
{
    uint64_t encoded = 0;
    for (uint8_t i = 0; i < 6; i++)
        encoded |= (uint64_t)inp[5 - i] << (8 * i);
    decode_callsign_value(outp, encoded);
}

functions.encode_callsign_value:
int8_t encode_callsign_value(uint64_t *out, const uint8_t *inp)
{
    if (strlen((const char *)inp) > 9)
        return -1;
    const uint8_t charMap[40] = " ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-/.";
    uint64_t tmp = 0;
    uint8_t start = 0;
    if (strcmp((const char *)inp, "@ALL") == 0)
    {
        *out = 0xFFFFFFFFFFFF;
        return 0;
    }
    if (inp[0] == '#')
        start = 1;
    for (int8_t i = strlen((const char *)inp) - 1; i >= start; i--)
    {
        for (uint8_t j = 0; j < 40; j++)
        {
            if (inp[i] == charMap[j])
            {
                tmp = tmp * 40 + j;
                break;
            }
        }
    }
    if (start)
        tmp += (262144000000000UL);
    *out = tmp;
    return 0;
}

functions.encode_callsign_bytes:
int8_t encode_callsign_bytes(uint8_t out[6], const uint8_t *inp)
{
    uint64_t tmp = 0;
    if (encode_callsign_value(&tmp, inp))
    {
        return -1;
    }
    for (uint8_t i = 0; i < 6; i++)
        out[5 - i] = (tmp >> (8 * i)) & 0xFF;
    return 0;
}

functions.CRC_M17:
uint16_t CRC_M17(const uint8_t *in, const uint16_t len)
{
    uint32_t crc = 0xFFFF;
    for (uint16_t i = 0; i < len; i++)
    {
        crc ^= in[i] << 8;
        for (uint8_t j = 0; j < 8; j++)
        {
            crc <<= 1;
            if (crc & 0x10000)
                crc = (crc ^ M17_CRC_POLY) & 0xFFFF;
        }
    }
    return crc & (0xFFFF);
}

functions.LSF_CRC:
uint16_t LSF_CRC(const lsf_t *in)
{
    uint8_t d[28];
    memcpy(&d[0], in->dst, 6);
    memcpy(&d[6], in->src, 6);
    memcpy(&d[12], in->type, 2);
    memcpy(&d[14], in->meta, 14);
    return CRC_M17(d, 28);
}

functions.extract_LICH:
void extract_LICH(uint8_t outp[6], const uint8_t cnt, const lsf_t *inp)
{
    switch (cnt)
    {
    case 0:
        outp[0] = inp->dst[0];
        outp[1] = inp->dst[1];
        outp[2] = inp->dst[2];
        outp[3] = inp->dst[3];
        outp[4] = inp->dst[4];
        break;
    case 1:
        outp[0] = inp->dst[5];
        outp[1] = inp->src[0];
        outp[2] = inp->src[1];
        outp[3] = inp->src[2];
        outp[4] = inp->src[3];
        break;
    case 2:
        outp[0] = inp->src[4];
        outp[1] = inp->src[5];
        outp[2] = inp->type[0];
        outp[3] = inp->type[1];
        outp[4] = inp->meta[0];
        break;
    case 3:
        outp[0] = inp->meta[1];
        outp[1] = inp->meta[2];
        outp[2] = inp->meta[3];
        outp[3] = inp->meta[4];
        outp[4] = inp->meta[5];
        break;
    case 4:
        outp[0] = inp->meta[6];
        outp[1] = inp->meta[7];
        outp[2] = inp->meta[8];
        outp[3] = inp->meta[9];
        outp[4] = inp->meta[10];
        break;
    case 5:
        outp[0] = inp->meta[11];
        outp[1] = inp->meta[12];
        outp[2] = inp->meta[13];
        outp[3] = inp->crc[0];
        outp[4] = inp->crc[1];
        break;
    default:;
        break;
    }
    outp[5] = cnt << 5;
}

