functions.golay24_encode:
uint32_t golay24_encode(const uint16_t data)
{
    uint16_t checksum = 0;
    for (uint8_t i = 0; i < 12; i++)
    {
        if (data & (1 << i))
        {
            checksum ^= encode_matrix[i];
        }
    }
    return ((uint32_t)data << 12) | checksum;
}

