functions.eucl_norm:
float eucl_norm(const float *in1, const int8_t *in2, const uint8_t n)
{
    float tmp = 0.0f;
    for (uint8_t i = 0; i < n; i++)
    {
        tmp += (in1[i] - (float)in2[i]) * (in1[i] - (float)in2[i]);
    }
    return sqrtf(tmp);
}

